import torch, b200probe, statistics, random
from cuda.bindings import runtime as rt
SRC = r'''
#include <stdint.h>
#define INNER 5120
#define V8 "{%0,%1,%2,%3,%4,%5,%6,%7}"
#define O8(v) "=f"(v[0]),"=f"(v[1]),"=f"(v[2]),"=f"(v[3]),"=f"(v[4]),"=f"(v[5]),"=f"(v[6]),"=f"(v[7])
extern "C" __global__ void empty_k(const float* x, float* y) {}
extern "C" __global__ void __launch_bounds__(128) ro256(const float* __restrict__ x, float* y) {
  long long row = blockIdx.y; int col = (blockIdx.x*128 + threadIdx.x)*8;
  const float* g = x + row*(2*INNER) + col; float a[8], b[8];
  asm volatile("ld.global.nc.v8.f32 " V8 ", [%8];" : O8(a) : "l"(g));
  asm volatile("ld.global.nc.v8.f32 " V8 ", [%8];" : O8(b) : "l"(g+INNER));
  float s=0; for(int i=0;i<8;i++) s+=a[i]*b[i];
  if (s == 1234.5f) y[0]=s;
}
extern "C" __global__ void __launch_bounds__(128) ro128(const float* __restrict__ x, float* y) {
  long long row = blockIdx.y; int col = (blockIdx.x*128 + threadIdx.x)*8;
  const float4* g = (const float4*)(x + row*(2*INNER) + col);
  const float4* l = (const float4*)(x + row*(2*INNER) + INNER + col);
  float4 a0=__ldg(g), a1=__ldg(g+1), b0=__ldg(l), b1=__ldg(l+1);
  float s=a0.x*b0.x+a0.y*b0.y+a0.z*b0.z+a0.w*b0.w+a1.x*b1.x+a1.y*b1.y+a1.z*b1.z+a1.w*b1.w;
  if (s == 1234.5f) y[0]=s;
}
// 128-bit with warp-contiguous 512B per instruction (4 floats per lane, two passes 2KB apart)
extern "C" __global__ void __launch_bounds__(128) ro128c(const float* __restrict__ x, float* y) {
  long long row = blockIdx.y; int col = blockIdx.x*1024 + threadIdx.x*4;
  const float* g = x + row*(2*INNER) + col;
  float4 a0=__ldg((const float4*)g), a1=__ldg((const float4*)(g+512)), b0=__ldg((const float4*)(g+INNER)), b1=__ldg((const float4*)(g+INNER+512));
  float s=a0.x*b0.x+a0.y*b0.y+a0.z*b0.z+a0.w*b0.w+a1.x*b1.x+a1.y*b1.y+a1.z*b1.z+a1.w*b1.w;
  if (s == 1234.5f) y[0]=s;
}
extern "C" __global__ void pf_l2(const float* __restrict__ x, float* y) {
  long long row = blockIdx.y; const float* g = x + row*(2*INNER) + blockIdx.x*1024;
  if (threadIdx.x==0) {
    asm volatile("cp.async.bulk.prefetch.L2.global [%0], 4096;" :: "l"(g) : "memory");
    asm volatile("cp.async.bulk.prefetch.L2.global [%0], 4096;" :: "l"(g+INNER) : "memory");
  }
}
extern "C" __global__ void __launch_bounds__(32) bulk_ro(const float* __restrict__ x, float* y) {
  __shared__ __align__(128) float buf[2048];
  __shared__ __align__(8) unsigned long long bar;
  long long row = blockIdx.y; const float* g = x + row*(2*INNER) + blockIdx.x*1024;
  unsigned sb = (unsigned)__cvta_generic_to_shared(buf), mb = (unsigned)__cvta_generic_to_shared(&bar);
  if (threadIdx.x==0) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" :: "r"(mb));
    asm volatile("fence.mbarrier_init.release.cluster;");
    asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], 8192;" :: "r"(mb));
    asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], 4096, [%2];" :: "r"(sb), "l"(g), "r"(mb) : "memory");
    asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], 4096, [%2];" :: "r"(sb+4096), "l"(g+INNER), "r"(mb) : "memory");
    asm volatile("{ .reg .pred p; W: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], 0; @!p bra W; }" :: "r"(mb) : "memory");
    if (buf[5] == 1234.5f) y[0] = buf[4100];
  }
}
'''
K = {n: b200probe.cuda_kernel(SRC, n) for n in ["empty_k","ro256","ro128","ro128c","pf_l2","bulk_ro"]}
blk = {"empty_k":128,"ro256":128,"ro128":128,"ro128c":128,"pf_l2":32,"bulk_ro":32}
flush = torch.empty(252*2**20//4, device="cuda"); clean = torch.randn(252*2**20//4, device="cuda")
def bench(names, rows, state, reps=15):
    n_in = rows*10240; src = torch.randn(n_in, device="cuda")
    xp = torch.empty(n_in+1024, device="cuda"); y = torch.zeros(1024, device="cuda")
    res = {n: [] for n in names}
    for r in range(reps):
        order = names[:] if r%2==0 else names[::-1]
        for n in order:
            off = random.randint(1,8)*64; x = xp[off:off+n_in]; x.copy_(src)
            rt.cudaCtxResetPersistingL2Cache(); flush.zero_()
            if state=="clean": clean.sum()
            e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
            e0.record(); K[n]((5,rows),(blk[n],),x,y); e1.record(); torch.cuda.synchronize()
            res[n].append(e0.elapsed_time(e1)*1e3)
    return {n: statistics.median(v) for n,v in res.items()}
names=["empty_k","ro256","ro128","ro128c","pf_l2","bulk_ro"]
for rows in (4096, 8192):
    for st in ("dirty","clean"):
        m = bench(names, rows, st)
        mb = rows*40960/1e6
        print(rows, st, " ".join(f"{n}={m[n]:.2f}us({mb/m[n]:.2f}TB/s)" for n in names))
# (e) L2 resident re-read 32 MB: 800 rows -> 32.8 MB
rows=800; x = torch.randn(rows*10240, device="cuda"); y=torch.zeros(1024,device="cuda")
for n in ["ro256","ro128c","bulk_ro"]:
    ts=[]
    for r in range(20):
        e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
        K[n]((5,rows),(blk[n],),x,y); e0.record(); K[n]((5,rows),(blk[n],),x,y); e1.record(); torch.cuda.synchronize(); ts.append(e0.elapsed_time(e1)*1e3)
    t=statistics.median(ts); print("L2-resident", n, f"{t:.2f}us {rows*40960/1e6/t:.2f}TB/s")

